from collections import deque
R,C=len(test),len(test[0])
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if test[r][c]!=7 and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); cells=[]
   while q:
    x,y=q.popleft();cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and test[nx][ny]!=7 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   vals=sorted({test[x][y] for x,y in cells})
   bbox=(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells))
   comps.append((len(cells),bbox,vals,cells))
for i,(n,bbox,vals,cells) in enumerate(comps):
 print(i, n,bbox,vals)
